/* Client experience preview. Role selection does not authenticate a person. */
let clientPage=new URLSearchParams(location.search).get('start')==='intake'?'intake':'home',clientEntered=requestedPortal==='client';
const clientShell=document.createElement('section');clientShell.id='client-shell';
clientShell.innerHTML=`<div id="client-entry"><div class="client-entry-brand"><img src="assets/eero-logo.png" alt="Eero Therapeutic Services"></div><div class="client-entry-layout"><div class="entry-story"><span class="eyebrow">YOUR NEXT STEP, MADE SIMPLE</span><h1>A little support.<br>A fresh start.</h1><p>A calm space to tell us what you need, share documents, and follow your request.</p><div class="entry-orbit" aria-hidden="true"><span>e</span><i></i><b></b></div></div><div class="entry-card"><span class="tiny-label">CLIENT PORTAL</span><h2>Welcome to Eero.</h2><p>See the simple experience a client or caregiver will use after signing in.</p><div class="entry-benefit">✓ A short intake form</div><div class="entry-benefit">✓ Photo and document uploads</div><div class="entry-benefit">✓ Your request, all in one place</div><button class="primary" id="client-enter">Open client preview →</button><small>Demonstration only. No password needed. Use fictional details.</small><a href="?portal=admin">Staff workspace preview ↗</a></div></div><div class="client-founder-intro"><div class="founder-initials"><img src="assets/kemi-idowu.jpg" alt="Kemi Idowu" width="76" height="76"></div><div><span class="tiny-label">MEET OUR FOUNDER</span><h2>Kemi Idowu</h2><p>MSW, LCSW, C-ACYFSW</p><p>Support for youth and families, grounded in understanding.</p></div><a class="secondary" href="kemi-idowu.html">Meet Kemi →</a></div><div class="client-entry-bottom"><a href="about-eero.html">About Eero &amp; contact →</a> <span>Care starts with connection.</span></div></div><div id="client-app" hidden><div class="client-topbar"><a href="?portal=client" aria-label="Eero client home"><img src="assets/eero-logo.png" alt="Eero Therapeutic Services"></a><div><span class="client-preview-chip">Client preview</span><button class="secondary" id="client-exit">Exit preview</button></div></div><nav class="client-nav" aria-label="Client portal"><button data-client-page="home">Home</button><button data-client-page="intake">Intake form</button><button data-client-page="documents">Documents</button><button data-client-page="status">My request</button></nav><div class="client-demo-note">Preview with fictional information only. Your sample stays in this browser.</div><div id="client-content"></div><div id="client-intake-slot"></div><div class="client-bottom"><span>Eero Therapeutic Services<br><a href="kemi-idowu.html">Meet Kemi Idowu →</a><br><a href="about-eero.html">About Eero &amp; contact →</a></span><p>This preview is not monitored for urgent help. In the U.S., call 911 for immediate danger or call/text 988 for crisis support.</p></div></div>`;
document.querySelector('footer').before(clientShell);$('client-intake-slot').append(intakePanel);
function ownIntakes(){const ids=new Set(state?.clientIntakeIds||[]);return (state?.intakes||[]).filter(i=>ids.has(i.id)).reverse()}
function latestClientIntake(){return ownIntakes()[0]}
function requestCard(i,full=false){if(!i)return `<div class="client-status-empty"><span class="client-soft-icon">${icon('review')}</span><h3>Your journey starts here.</h3><p>Complete a short intake form to create your first sample request.</p><button class="secondary" data-client-page="intake">Start intake →</button></div>`;const stages=['New','In review','Assigned'],position=stages.indexOf(i.status);return `<article class="client-request-card"><div class="client-request-head"><div><small>REQUEST ${esc(i.id.slice(0,8).toUpperCase())}</small><h3>${esc(i.name)}</h3></div><span class="age-tag">${esc(i.status==='New'?'Submitted':i.status==='Assigned'?'Assigned':i.status)}</span></div><div class="client-request-stages">${['Submitted','In review','Assigned'].map((x,n)=>`<div class="${n<=position?'done':''}"><i>${n<position?'✓':n+1}</i><span>${x}</span></div>`).join('')}</div><p>${i.status==='Assigned'?'Your sample request has been assigned in the staff workspace.':i.status==='In review'?'Your sample request is marked for review in the staff workspace.':'Your sample introduction is saved and appears in the staff intake inbox.'}</p>${full?`<dl class="client-request-details"><dt>Submitted</dt><dd>${esc(new Date(i.createdAt).toLocaleDateString())}</dd><dt>Service preference</dt><dd>${esc(i.service)}</dd><dt>Documents</dt><dd>${(i.files||[]).length} attached</dd></dl>`:''}<small>No email or notification was sent. This is a browser-local demonstration.</small></article>`}
function clientHomeHTML(){const i=latestClientIntake();return `<div class="client-home-welcome"><div><span class="eyebrow">YOUR EERO SPACE</span><h1>Welcome.<br>Let’s take the next step.</h1><p>Tell us a little about yourself. We’ll keep each step clear and simple.</p><button class="primary" data-client-page="intake">${i?'Start another sample intake':'Get started with intake'} →</button></div><div class="client-welcome-art" aria-hidden="true"><div>e</div><span></span></div></div><div class="client-actions-grid"><button data-client-page="intake"><span class="client-soft-icon">${icon('review')}</span><h2>Fill out your intake</h2><p>A few details to help the team understand your needs.</p><small>About 4 simple steps ↗</small></button><button data-client-page="documents"><span class="client-soft-icon">${icon('upload')}</span><h2>Share a document</h2><p>Take a photo or upload a form. No printing required.</p><small>Photo or PDF ↗</small></button><button data-client-page="status"><span class="client-soft-icon">${icon('calendar')}</span><h2>Follow your request</h2><p>See whether your introduction is submitted, in review, or assigned.</p><small>View your progress ↗</small></button></div><div class="client-section-title"><h2>Your latest request</h2><button class="text-link" data-client-page="status">View details →</button></div>${requestCard(i)}<div class="client-founder-intro"><div class="founder-initials"><img src="assets/kemi-idowu.jpg" alt="Kemi Idowu" width="76" height="76"></div><div><span class="tiny-label">THE PERSON BEHIND EERO</span><h2>Kemi Idowu</h2><p>MSW, LCSW, C-ACYFSW · Founder</p></div><a class="secondary" href="kemi-idowu.html">View profile →</a></div>`}
function clientDocumentsHTML(){const i=latestClientIntake();return `<div class="client-page-heading"><span class="eyebrow">YOUR DOCUMENTS</span><h1>Snap it. Share it.</h1><p>Attach a fictional photo or PDF to your latest sample request.</p></div>${i?`<div class="client-upload-card"><p>Request <strong>${esc(i.id.slice(0,8).toUpperCase())}</strong> · ${esc(i.name)}</p><div class="capture-options"><label class="capture-button">${icon('capture')}<strong>Take a photo</strong><small>Use your phone camera</small><input id="client-doc-camera" type="file" accept="image/jpeg,image/png" capture="environment" hidden></label><label class="capture-button">${icon('upload')}<strong>Choose a file</strong><small>PNG, JPEG or PDF · 15 MB</small><input id="client-doc-files" type="file" accept="image/jpeg,image/png,application/pdf" multiple hidden></label></div><p class="muted">Files are saved in this browser and placed with the sample intake for staff review. No AI extraction runs here.</p></div><div class="client-doc-list">${(i.files||[]).map((f,n)=>`<article><span class="client-soft-icon">${icon('review')}</span><div><strong>${esc(f.name)}</strong><small>${(f.size/1024).toFixed(0)} KB · Attached to intake</small></div><button class="secondary" data-client-file="${n}">Download</button></article>`).join('')||'<div class="client-empty">No documents yet. You can add one above.</div>'}</div>`:requestCard(null)}`}
function clientStatusHTML(){const items=ownIntakes();return `<div class="client-page-heading"><span class="eyebrow">MY REQUEST</span><h1>One clear next step.</h1><p>Follow your sample introductions and the staff review process.</p></div>${items.map(i=>requestCard(i,true)).join('')||requestCard(null)}`}
function paintClient(){const active=portalRole==='client';clientShell.hidden=!active;if(!active)return;document.body.classList.add('client-mode');$('client-entry').hidden=clientEntered;$('client-app').hidden=!clientEntered;intakePanel.hidden=!clientEntered||clientPage!=='intake';$('client-content').hidden=clientPage==='intake';clientShell.querySelectorAll('[data-client-page]').forEach(b=>b.classList.toggle('active',b.dataset.clientPage===clientPage));if(clientPage!=='intake')$('client-content').innerHTML=clientPage==='documents'?clientDocumentsHTML():clientPage==='status'?clientStatusHTML():clientHomeHTML();clientShell.querySelectorAll('.client-nav button').forEach(b=>{const selected=b.dataset.clientPage===clientPage;b.classList.toggle('active',selected);b.setAttribute('aria-current',selected?'page':'false')});if(clientPage==='documents'&&latestClientIntake()){for(const id of ['client-doc-camera','client-doc-files'])$(id).onchange=e=>saveClientAttachments(Array.from(e.target.files))}}
async function saveClientAttachments(files){const i=latestClientIntake();if(!i)return;const valid=files.filter(f=>f.size>0&&f.size<=15*1024*1024&&['image/jpeg','image/png','application/pdf'].includes(f.type));if(valid.length!==files.length)toast('Use PNG, JPEG or PDF files up to 15 MB each.');if(!valid.length)return;i.files??=[];const oldFiles=[...i.files],oldDocs=[...state.docs];i.files.push(...valid);if(i.caseId)for(const f of valid)state.docs.push({id:uid(),caseId:i.caseId,title:f.name,type:'Referral',date:today(),notes:'Client sample attachment added after intake. Requires staff review.',status:'Needs review',blob:f,events:['Attached from client portal preview']});try{await persist();toast('Sample documents attached for staff review.')}catch{i.files=oldFiles;state.docs=oldDocs;render();toast('Could not save files. Check browser storage.')}}
function goClientPage(page){if(!['home','intake','documents','status'].includes(page))return;clientPage=page;if(page==='intake'&&$('client-intake-form').hidden){$('new-intake-again')?.click()}render();window.scrollTo({top:0,behavior:'smooth'})}
clientShell.onclick=e=>{const b=e.target.closest('[data-client-page]');if(b)goClientPage(b.dataset.clientPage);const file=e.target.closest('[data-client-file]');if(file){const f=latestClientIntake()?.files[Number(file.dataset.clientFile)];if(f){const url=URL.createObjectURL(f),a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}};
$('client-enter').onclick=()=>{clientEntered=true;clientPage='home';render()};$('client-exit').onclick=()=>{clientEntered=false;clientPage='home';render();window.scrollTo(0,0)};
const clientOriginalSubmit=$('client-intake-form').onsubmit;$('client-intake-form').onsubmit=async e=>{const before=new Set((state.intakes||[]).map(i=>i.id));await clientOriginalSubmit(e);const item=(state.intakes||[]).find(i=>!before.has(i.id));if(!item||$('client-receipt').hidden)return;state.clientIntakeIds??=[];state.clientIntakeIds.push(item.id);try{await persist()}catch{toast('Sample saved; request tracking could not be updated.')}const handoff=$('show-admin-intake');handoff.textContent='View my request →';handoff.onclick=()=>goClientPage('status');$('new-intake-again').textContent='Start another sample';document.querySelector('.intake-card').hidden=true};
const clientNewStep=showIntakeStep;showIntakeStep=function(){clientNewStep();document.querySelector('.intake-card').hidden=$('client-intake-form').hidden};
const clientPriorRender=render;render=function(){clientPriorRender();paintClient()};
if(state)render();
